// Part: chimneys, stairs, hearths, job sites
import { chimney, flight, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { jobSite } from "../vocab.mjs";

function ladder(g, x, y0, y1, z, facing) {
  for (let y = y0; y <= y1; y++) g.set(x, y, z, "ladder", { facing });
}

// Cells of earlier parts' roof eaves where a flue passes through: the barn's back eave (65,13,15) and the owner's eave
// (90,9,16), (92,9,16). Earlier parts are locked, so the chimney keeps the roof's blocks there instead of writing over
// them (the library refuses those three writes, and the roof part has to own the fix).
const EAVE_KEPT = new Set(["65,13,15", "90,9,16", "92,9,16"]);

// The chimney writes its whole stack; EAVE_KEPT cells are skipped and warned, every other write lands as before.
function chimneyKeepingEaves(g, c) {
  const kept = [];
  const skipEaves = new Proxy(g, {
    get(t, p) {
      if (p === "set") return (x, y, z, b, s) => { const k = `${x},${y},${z}`; if (EAVE_KEPT.has(k)) kept.push(k); else t.set(x, y, z, b, s); return t; };
      const v = Reflect.get(t, p);
      return typeof v === "function" ? v.bind(t) : v;
    },
  });
  chimney(skipEaves, c);
  if (kept.length) console.warn("chimney", c.wall, "kept the roof's eave at", kept.join(" "));
}

export function build(g) {
  const notes = [];
  // chimneys, called directly (they lay their own footing and cut the mouth)
  const chims = [
    { wall: [32, 2, 15], into: "west", top: 13 },
    { wall: [40, 1, 15], into: "north", top: 12 },
    { wall: [65, 1, 15], into: "north", top: 13 },
    { wall: [91, 2, 15], into: "north", top: 16 },
  ];
  for (const c of chims) {
    try { chimneyKeepingEaves(g, { ...c, material: "bricks" }); } catch (e) { console.warn("chimney", c.wall, e.message); }
  }
  // flights
  for (const f of [
    { from: [26, 2, 13], facing: "east", to: 6, material: "spruce" },
    { from: [86, 2, 14], facing: "north", to: 6, material: "spruce" },
  ]) {
    try { const r = flight(g, f); if (r.notes?.length) console.warn("flight", r.notes); } catch (e) { console.warn("flight", e.message); }
  }
  // ladders
  ladder(g, 2, 1, 6, 15, "east");
  ladder(g, 52, 9, 15, 11, "north");
  ladder(g, 55, 2, 7, 16, "west");
  ladder(g, 64, 1, 9, 14, "east");
  // job sites
  jobSite(g, "cartography_table", [21, 2, 16], { facing: "north" });
  jobSite(g, "smithing_table", [43, 1, 14], { facing: "west" });
  jobSite(g, "anvil", [42, 1, 12], { facing: "north" });
  jobSite(g, "lectern", [52, 2, 16], { facing: "north" });
  jobSite(g, "composter", [78, 2, 15], { facing: "north" });
  // forge quench
  g.set(41, 1, 14, "water_cauldron", { level: "3" });
}

// Part: room: tobacco barn (interior designer). Inner air x 64..67, y 1..13, z 10..14; door x 65..66 z 9; firebox
// mouth (65, 1, 15) in the back wall; ladder (64, 1..9, 14) built earlier by the hearths part (locked).
// Layout: a clear 2-wide lane x 65..66 from the door to the ladder foot; storage and the stripping table along the
// east and west walls; tier poles with hung leaves overhead (the focal piece, seen from the door); lanterns low.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { tobaccoTier } from "../vocab.mjs";

export function build(g) {
  // the tobacco tiers: poles along x at y 5, 7, 9 on rows z 10, 12, 14, leaves hung under them (the ladder's cells skip)
  tobaccoTier(g, 64, 10, [5, 7, 9]);

  // floor layer y 1 (rows z 10..14, columns x 64..67; ' ' = leave as is: the ladder foot at (64,1,14) is locked)
  layers(g, [64, 1, 10], {
    b: "barrel",
    h: "hay_block",
    L: ["lantern", { hanging: "false" }],
  }, [
    ["b..b",   // z 10: leaf barrels in the two back corners
     "h..h",   // z 11: hay bales, storage and a seat for the stripping
     "L...",   // z 12: a standing lantern low on the west wall
     "...b",   // z 13: the stripping table (a barrel with a candle on it)
     "...."],  // z 14: clear, the ladder foot beside it
  ]);

  // y 2: candles lit on the barrel tops (warm light at the bench and the leaf store)
  const candle = ["candle", { candles: "4", lit: "true", waterlogged: "false" }];
  layers(g, [64, 2, 10], { c: candle }, [
    ["c..c",
     "....",
     "....",
     "...c",
     "...."],
  ]);

  // a hanging lantern under the west tier pole, for the room's height
  g.set(64, 4, 12, "lantern", { hanging: "true", waterlogged: "false" });
}

// Part: room: corn crib bin (interior designer). The bin is one cell wide (x 74) and six deep (z 10..15), floor y 3,
// entered from the hatch at (74, 3..4, 9). The clear column z 10..13 stays open from the hatch; the corn heap fills
// the far end, and a standing lantern on its top lights the bin.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // rows run along +z (one cell wide, so one character per row), layers run up from y 3
  layers(
    g,
    [74, 3, 14],
    {
      h: "hay_block", // corn heap (ears stored as hay: no corn block in the palette)
      L: ["lantern", { hanging: "false" }], // standing on the heap's top, the focal light
    },
    [
      ["h", "h"], // y 3: heap on the floor at z 14..15
      [" ", "h"], // y 4: the heap's top course at z 15
      [" ", "L"], // y 5: the lantern on it
    ],
  );
}

