// Part: room: owner stair hall (interior). The flight x86 z14->10 is built and locked; this furnishes only the air
// cells round it (the box is one column wide, so the hall is the stair well). A coat rack at the north end where the
// hall meets the parlor opening, and a lantern hung from the stair's stringer so the climb is lit.
// Palette-only: no banner (not in palette.json), so the coat rack is a fence post with a lantern standing on it.

export function build(g) {
  // Coat rack: a spruce fence post on the floor, a standing lantern on its top (the hook and the light)
  g.set(86, 2, 10, "minecraft:spruce_fence");
  g.set(86, 3, 10, "minecraft:lantern", { hanging: "false", waterlogged: "false" });

  // Lantern hanging from the stair's top stringer at the north end (stringer at 86,5,10 is a block above it)
  g.set(86, 4, 10, "minecraft:lantern", { hanging: "true", waterlogged: "false" });
}

// Part: room: owner upper bedrooms. Interior: x 86..91, z 10..14, floor stand y 7, air to y 10.
// Keep clear (built by others): the flight's landing and headroom at x 86 z 10..12 and the rail at x 87 z 11..12; the
// balcony doorway's first cells x 86..87 z 14 (y 7..8). The lane runs x 88 (z 10..14), then x 89 north-south, so the
// stair landing, the balcony doors and every bed foot are joined. Beds (plan: 4) come to 3 here: the plan's south bed at
// x 88 z 13..14 walls the balcony doors off, so it moves to x 90 z 13..14 (see plan.md Notes).
// Light: a standing lantern on the dresser (focal, in the window's view), a standing lantern on the work table, a lit
// candle by the back bed. Nothing over the east windows at x 92 z 11 and z 13 (y 8..9).
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // Floor level (y 7): barrels (dresser, pocket), the table post, the chair. Rows run along +x (x 86..91), z 10..14.
  layers(g, [86, 7, 10], {
    "s": ["pale_oak_stairs", { facing: "east", half: "bottom", shape: "straight" }],
    "f": "pale_oak_fence",
    "b": "barrel",
  }, [
    "      ",   // z 10: landing and lane
    "    bb",   // z 11: dresser barrels under the east window (x 90..91)
    "      ",   // z 12: lane
    "sf   b",   // z 13: chair (x 86), table post (x 87), pocket barrel (x 91)
    "     b",   // z 14: pocket barrel (x 91)
  ]);

  // Top level (y 8): the table top slab, the dresser lantern, the lit candle on the pocket barrel.
  layers(g, [86, 8, 10], {
    "t": ["smooth_stone_slab", { type: "top" }],
    "L": ["lantern", { hanging: "false" }],
    "c": ["candle", { candles: "2", lit: "true" }],
  }, [
    "      ",
    "    L ",   // z 11: lantern on the dresser barrel (x 90), nothing in front of the window (x 91)
    "      ",
    " t    ",   // z 13: table top (x 87)
    "     c",   // z 14: lit candle on the pocket barrel (x 91)
  ]);

  // Light on the table top (y 9): the table lantern stands on the top slab.
  layers(g, [86, 9, 10], {
    "L": ["lantern", { hanging: "false" }],
  }, [
    "      ",
    "      ",
    "      ",
    " L    ",   // z 13: lantern on the table top (x 87)
    "      ",
  ]);

  // Beds: whole, heads against solid walls. East beds: heads at x 91 against x 92 (z 10, z 12).
  // South bed: foot z 13, head z 14 against the back wall z 15.
  bed(g, [90, 7, 10], "east", "red");
  bed(g, [90, 7, 12], "east", "blue");
  bed(g, [90, 7, 13], "south", "white");
}

// Part: room: owner parlor and dining. Inner air x 87..91, y 2..5, z 10..14 (rooms.json box 87,2,10,91,5,14).
// Layout: the hearth (furnace, stove) is the focal piece on the back wall at (91,2,14), in line with the front door.
// A pale oak settee and armchairs face it; the dining table (fence + top slab) sits in the middle with four chairs
// (pale oak stairs, backs out); a barrel cabinet in the front corner and a side table by the east window.
// Lanes kept clear: door (89..90, z10) to the east lane x91, and the stair foot (87, 2, 13..14) via the back row.
// Light: a hanging lantern over the table, a lit candle on the stove, the barrel and the side table.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const ORIGIN = [87, 2, 10];

// y 2: floor-level furniture (rows z 10..14, columns x 87..91)
const FLOOR = [
  "B...T", // z10: barrel cabinet, door lane clear, side table by the east window
  "S.N..", // z11: settee end, chair north of the table, east lane clear
  "SWTE.", // z12: settee end, chair west, table, chair east
  "..Z..", // z13: chair south of the table, stair-foot lane clear
  "....H", // z14: stove on the back wall, in front of the hearth mouth (91,2,15)
];
// y 3: things on tops (candles on the barrel, the table and the stove; the side table's top slab)
const TOPS = [
  "c...Q",
  ".....",
  "..Q..",
  ".....",
  "....h",
];
// y 4: candle on the side table's top
const UPPER = [
  "....k",
  ".....",
  ".....",
  ".....",
  ".....",
];
// y 5: hanging lantern from the upper floor's ceiling, over the table
const HANG = [
  ".....",
  ".....",
  "..L..",
  ".....",
  ".....",
];

const LEGEND = {
  B: ["barrel", { facing: "up", open: "false" }],
  T: "spruce_fence",
  S: ["mangrove_stairs", { facing: "west", half: "bottom" }], // settee: back to the west wall, seat facing east
  N: ["mangrove_stairs", { facing: "north", half: "bottom" }], // chairs: backs out, seats toward the table
  W: ["mangrove_stairs", { facing: "west", half: "bottom" }],
  E: ["mangrove_stairs", { facing: "east", half: "bottom" }],
  Z: ["mangrove_stairs", { facing: "south", half: "bottom" }],
  Q: ["smooth_stone_slab", { type: "top" }],
  H: ["furnace", { facing: "north", lit: "false" }],
  c: ["candle", { candles: "1", lit: "true" }],
  h: ["candle", { candles: "1", lit: "true" }],
  k: ["candle", { candles: "1", lit: "true" }],
  L: ["lantern", { hanging: "true" }],
};

export function build(g) {
  layers(g, ORIGIN, LEGEND, [FLOOR, TOPS, UPPER, HANG]);
}

