content.content:
1	// Part: roofs (P3). Every plot's main roof through the library's roof() (one call per building, so each keeps its own
2	// style, pitch, palette and keep boxes for its stacks and cupola), then the hand-built pieces the roof tool does not
3	// make: the farmhouse porch shed, the forge and barn lean-tos, the cupola cap and the church spire (vocab spireCap).
4	// Coordinates per plan.md ROOFS. Runs after the shells, so the walls are built and each roof stands on them. No roof.json:
5	// the roof is laid here per building, which runParts' single roof spec cannot do for eight different styles.
6	import { roof, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
7	import { spireCap } from "./../vocab/h3.mjs";
8	
9	const PALETTE_SLATE = { mix: [["deepslate_tiles", 3], ["cobblestone", 1], ["deepslate_bricks", 1]], eave: "cobblestone", ridge: "deepslate_tiles", verge: "stripped_spruce_log" };
10	
11	// The roof tool derives its stair and slab forms from each material's name (its verge, trim and mix defaults), and some
12	// of those forms are not in palette.json. Each is swapped at the write for the palette block of the same shape.
13	const FORM_SWAP = {
14	  deepslate_brick_stairs: "deepslate_tile_stairs", deepslate_brick_slab: "deepslate_tile_slab",
15	  polished_andesite_stairs: "andesite_stairs",
16	  stripped_spruce_log_stairs: "spruce_stairs", stripped_spruce_log_slab: "spruce_slab",
17	  dark_oak_stairs: "mangrove_stairs", dark_oak_slab: "mangrove_slab",
18	  oak_stairs: "bamboo_stairs", oak_slab: "bamboo_slab",
19	  stripped_oak_log_stairs: "bamboo_stairs", stripped_oak_log_slab: "bamboo_slab",
20	  stripped_dark_oak_log_stairs: "waxed_exposed_cut_copper_stairs", stripped_dark_oak_log_slab: "waxed_exposed_cut_copper_slab",
21	  // the crib and granary mix (bamboo, oak) is widened by the texture's tone-matched neighbours: the grey members are not in
22	  // palette.json, so each takes the grey palette block of its shape
23	  tuff_brick_stairs: "stone_brick_stairs", tuff_bricks: "stone_bricks",
24	  cobbled_deepslate_stairs: "deepslate_tile_stairs", polished_deepslate_stairs: "deepslate_tile_stairs", polished_deepslate: "deepslate_tiles",
25	};
26	// The shell's cells are locked: a roof write into a block an earlier part built (the calcite cornice on the church's side
27	// walls at y 8) is dropped here, not sent on to be refused. Cells this part has already written stay open to the roof.
28	function paletteForms(g) {
29	  const placed = new Set();
30	  return new Proxy(g, {
31	    get(target, prop) {
32	      if (prop === "set") return (x, y, z, block, state, nbt) => {
33	        const key = `${x},${y},${z}`, there = target.get(x, y, z);
34	        if (there && !/(^|_)air$/.test(there.block) && !placed.has(key)) return;
35	        placed.add(key);
36	        const id = String(block).replace(/^minecraft:/, "");
37	        return target.set(x, y, z, FORM_SWAP[id] ? `minecraft:${FORM_SWAP[id]}` : block, state, nbt);
38	      };
39	      const v = Reflect.get(target, prop);
40	      return typeof v === "function" ? v.bind(target) : v;
41	    },
42	  });
43	}
44	
45	// A lean-to or shed row: stairs stepping up toward the wall, one stair per cell along the run.
46	function leanTo(g, cells, facing, state) {
47	  for (const [x, y, z] of cells) g.set(x, y, z, ...B.stairs(state.mat, facing, "bottom"));
48	}
49	
50	// A stepped cone of rings, each ring one course higher than the last and stepped in one cell a side (cupola cap).
51	function stepCap(g, [x0, z0, x1, z1], y, rows, mat) {
52	  for (let r = 0; r < rows; r++) {
53	    const xa = x0 + r, xb = x1 - r, za = z0 + r, zb = z1 - r;
54	    if (xa > xb || za > zb) break;
55	    for (let x = xa; x <= xb; x++) {
56	      g.set(x, y + r, za, ...B.stairs(mat, "south", "bottom"));
57	      g.set(x, y + r, zb, ...B.stairs(mat, "north", "bottom"));
58	    }
59	    for (let z = za + 1; z <= zb - 1; z++) {
60	      g.set(xa, y + r, z, ...B.stairs(mat, "east", "bottom"));
61	      g.set(xb, y + r, z, ...B.stairs(mat, "west", "bottom"));
62	    }
63	  }
64	}
65	
66	export function build(grid) {
67	  const g = paletteForms(grid);
68	  // plot 0: cotton gin, tall front gable to the lane, louvred monitor on the ridge; keep the hoist beam and the hay door
69	  // no fascia board: at overhang 1 it would sit at x -1, off the row, and roof() would grow the grid and shift every cell
70	  roof(g, [[1, 9, 10, 16]], "granary", {
71	    y: 10, ridgeAxis: "z", front: "n", pitch: 1, material: PALETTE_SLATE, verge: "stripped_spruce_log", overhang: 1,
72	    edges: { fascia: false }, keep: [{ from: [6, 8, 7], to: [6, 10, 9] }],
73	  });
74	
75	  // plot 1: schoolhouse, steep gable on the classroom; cloakroom porch with its own lower gable; the cupola stands through
76	  // the back eave stops at the ring (z 18): an overhang to z 19 would leave the row
77	  roof(g, [[13, 11, 22, 18]], "cottage", {
78	    y: 7, ridgeAxis: "z", front: "n", pitch: 1, material: { mix: [["andesite", 3], ["polished_andesite", 1]], eave: "stone_bricks", ridge: "andesite", verge: "stripped_spruce_log" },
79	    overhang: { north: 1, south: 0, east: 1, west: 1 },
80	    keep: [{ from: [16, 7, 13], to: [19, 16, 16] }],
81	  });
82	  // its back is the classroom's front wall (z 12): the roof stops at z 11 and dies into that wall, no south overhang
83	  roof(g, [[15, 9, 20, 11]], "gable", {
