/** Is a lit campfire a proper hearth fire? Its smoke must find an open flue (air or a thin trapdoor's cell) straight
 *  up to the sky, walled on all four sides above the firebox, and its hay (if any) hidden. Returns [] or the faults. */
export function hearthFaults(at, [x, y, z], sizeY) {
  const name = (cx, cy, cz) => String(at(cx, cy, cz)?.block ?? "air").replace(/^minecraft:/, "");
  const faults = [];
  if (/cauldron$/.test(name(x, y + 1, z))) return faults;                         // a wash kettle or a stewpot over the fire
  let cy = y + 1, blocked = null;
  const walls = (yy) => Object.values(DIRS).filter(([dx, dz]) => !AIRY.test(name(x + dx, yy, z + dz)) || /trapdoor$/.test(name(x + dx, yy, z + dz))).length;
  for (; cy < sizeY; cy++) { const b = name(x, cy, z); if (!/(^|_)air$|trapdoor$/.test(b)) { blocked = b; break; } }
  // the flue runs up to its mouth: the last course with any wall beside it (above that is the sky)
  let mouth = y;
  for (let yy = y + 1; yy < cy; yy++) if (walls(yy)) mouth = yy;
  let open = 0;
  for (let yy = y + 1; yy <= mouth; yy++) open += 4 - walls(yy);
  const height = Math.max(1, mouth - y), under = name(x, y - 1, z);
  // a fire perched on a stack (air or roof beside what it stands on) belongs in the hearth at the bottom
  if (!blocked && mouth === y && (/hay_block/.test(under) || Object.values(DIRS).some(([dx, dz]) => /(^|_)air$|stairs|slab/.test(name(x + dx, y - 1, z + dz)))))
    return ["it sits on top of the stack: a chimney's fire burns at the bottom, in the hearth, and its smoke rises up the flue"];
  if (!blocked && mouth === y) return faults;                                      // an open-air fire (a firepit, a camp): fine
  if (!Object.values(DIRS).some(([dx, dz]) => AIRY.test(name(x + dx, y, z + dz)) && !/trapdoor$/.test(name(x + dx, y, z + dz))))
    faults.push("it is shut inside the stack with no firebox mouth: a chimney's fire burns at the bottom, in a hearth open to the room");
  if (blocked) faults.push(`its smoke hits ${blocked} ${cy - y} above: give it an open flue of air up to the sky`);
  if (open) faults.push(`the flue is open on ${open} side${open > 1 ? "s" : ""} above the firebox: wall it (masonry, or an open trapdoor lying flat against the flue)`);
  for (let yy = y + 2; yy <= mouth; yy++) {
    const tile = Object.values(DIRS).map(([dx, dz]) => name(x + dx, yy, z + dz)).find((b) => /_stairs$|_slab$/.test(b));
    if (tile) { faults.push(`the roof's ${tile} walls the flue at y ${yy}: carry the chimney's own masonry through the roof, the roof stopping against it`); break; }
  }
  if (/hay_block/.test(under) && Object.values(DIRS).some(([dx, dz]) => AIRY.test(name(x + dx, y - 1, z + dz)))) faults.push("the hay bale under it shows: set it into the floor");
  return faults;
}
