11	  const [b, s] = Array.isArray(what) ? what : [what];
12	  for (let x = box[0]; x <= box[3]; x++)
13	    for (let y = box[1]; y <= box[4]; y++)
14	      for (let z = box[2]; z <= box[5]; z++)
15	        if (!holes.some((h) => inBox(x, y, z, h))) s ? g.set(x, y, z, b, s) : g.set(x, y, z, b);
16	}
17	const post = (g, x, z, y0, y1) => put(g, [x, y0, z, x, y1, z], B.pillar(SL, "y"));
