21	  const runs = [[x0, z0, x1, z0], [x0, z1, x1, z1], [x0, z0 + 1, x0, z1 - 1], [x1, z0 + 1, x1, z1 - 1]];
22	  for (const [a, b, c, d] of runs) {
23	    if (plinth) put(g, [a, y0, b, c, y0, d], plinthBlock, holes);
24	    put(g, [a, y0 + (plinth ? 1 : 0), b, c, y1, d], body, [...holes, ...skip]);
