31	// Board-and-batten run for the open-front buildings: field plus a batten every 3rd column.
32	function batten(g, [x0, z0, x1, z1], y0, y1, plank, holes = []) {
33	  const alongX = z0 === z1;
34	  put(g, [x0, y0, z0, x1, y1, z1], plank, holes);
35	  for (let i = 0; i <= (alongX ? x1 - x0 : z1 - z0); i += 3) {
36	    const x = alongX ? x0 + i : x0, z = alongX ? z0 : z0 + i;
37	    put(g, [x, y0, z, x, y1, z], B.pillar(SL, "y"), holes);
38	  }
39	}
