41	function gin(g) {
42	  const holes = [
43	    [4, 0, 9, 7, 4, 9], [5, 7, 9, 6, 8, 9],            // wagon door, hay door
44	    [5, 1, 16, 6, 3, 16], [3, 2, 16, 3, 3, 16], [8, 2, 16, 8, 3, 16], // back door, windows
45	    [1, 2, 11, 1, 3, 11], [10, 2, 11, 10, 3, 11],      // ground side windows
46	    [1, 8, 11, 1, 8, 11], [10, 8, 11, 10, 8, 11], [1, 8, 14, 1, 8, 14], [10, 8, 14, 10, 8, 14], // loft windows
47	    [10, 2, 14, 10, 2, 14],                            // shaft port
48	  ];
49	  const jambs = [[1, 9], [10, 9], [1, 16], [10, 16], [3, 9], [8, 9]];
50	  ring(g, [1, 9, 10, 16], { y0: 1, y1: 9, plinth: true, body: "minecraft:birch_planks", holes, posts: jambs, beams: [6, 9] });
51	  // floor: cobblestone at grade, the shaft frame's 3x3 left to shaftFrame
52	  put(g, [2, 0, 10, 9, 0, 15], "minecraft:cobblestone", [[6, 0, 13, 8, 0, 15]]);
53	  shaftFrame(g, 6, 0, 13, { port: true });
54	  // loft floor y6 with the shaft hole and the ladder hole
55	  put(g, [2, 6, 10, 9, 6, 15], "minecraft:spruce_planks", [[7, 6, 14, 7, 6, 14], [2, 6, 15, 2, 6, 15]]);
56	}
57	
58	function school(g) {
59	  const stone = "minecraft:stone_bricks", wall = "minecraft:white_concrete";
60	  const clsHoles = [[13, 2, 13, 13, 5, 13], [22, 2, 13, 22, 5, 13], [13, 2, 15, 13, 5, 15], [22, 2, 15, 22, 5, 15], [17, 5, 17, 18, 5, 17],
61	    [17, 2, 12, 18, 3, 12]];
62	  const clkHoles = [[17, 2, 9, 18, 4, 9], [15, 3, 10, 15, 4, 10], [20, 3, 10, 20, 4, 10]];
63	  ring(g, [13, 12, 22, 17], { y0: 1, y1: 6, plinth: true, plinthBlock: stone, body: wall, holes: clsHoles,
64	    posts: [[13, 12], [22, 12], [13, 17], [22, 17]] });
65	  // cloakroom: its back is the classroom's front wall (z12), so it only builds the front and sides
66	  const sides = [[15, 9, 20, 9], [15, 10, 15, 11], [20, 10, 20, 11]];
67	  for (const [a, b, c, d] of sides) {
68	    put(g, [a, 1, b, c, 1, d], stone, clkHoles);
69	    put(g, [a, 2, b, c, 4, d], wall, clkHoles);
70	  }
71	  for (const [x, z] of [[15, 9], [20, 9]]) post(g, x, z, 2, 4);
72	  // floors y1 (stand y2)
73	  put(g, [14, 1, 13, 21, 1, 16], "minecraft:spruce_planks");
74	  put(g, [16, 1, 10, 19, 1, 12], "minecraft:spruce_planks");
