79	    [29, 2, 10, 30, 3, 10], [26, 3, 10, 27, 4, 10], [32, 3, 10, 33, 4, 10],   // door + sidelight, windows
80	    [25, 3, 12, 25, 4, 12], [34, 3, 12, 34, 4, 12],                           // side windows
81	    [31, 2, 14, 31, 3, 14],                                                    // body -> kitchen door
