84	  // footing line y1: cobblestone piers at corners and every 3, spruce planks (floor edge) between
85	  const line = (x0, z0, x1, z1) => {
86	    const alongX = z0 === z1, n = alongX ? x1 - x0 : z1 - z0;
87	    for (let i = 0; i <= n; i++) {
88	      const x = alongX ? x0 + i : x0, z = alongX ? z0 : z0 + i;
89	      put(g, [x, 1, z, x, 1, z], i % 3 === 0 || i === n ? "minecraft:cobblestone" : "minecraft:spruce_planks", holes);
90	    }
91	  };
92	  line(25, 10, 34, 10); line(25, 14, 32, 14); line(25, 11, 25, 13); line(34, 11, 34, 13);
93	  // body walls y2..7
94	  const bw = (box) => boardWall(g, box, { plank: "minecraft:spruce_planks", batten: 3, beams: [5], leave: holes });
95	  bw([25, 2, 10, 34, 7, 10]); bw([25, 2, 14, 32, 7, 14]);
