99	  const eh = [[26, 2, 16, 26, 3, 16], [29, 3, 17, 30, 4, 17], [32, 2, 15, 32, 2, 15]];
100	  const ew = (box) => boardWall(g, box, { plank: "minecraft:spruce_planks", batten: 3, beams: [4], leave: eh });
101	  ew([26, 2, 15, 26, 4, 17]); ew([32, 2, 15, 32, 4, 17]); ew([27, 2, 17, 31, 4, 17]);
102	  // floors y1 and the loft floor y6 (flight cells left open)
103	  put(g, [26, 1, 11, 33, 1, 13], "minecraft:spruce_planks");
