/** A monitor (louvred ridge vent) over the middle 60% of each gable ridge: two-high louvre walls of open trapdoors
 *  either side of the ridge, capped by a small roof (stairs over the louvres, a full block and slab on top). */
function monitor(W, ridgeCells, axis, rects, mat) {
  let placed = 0;
  for (const r of ridgeCells) {
    if (r.pair && !(r.pair === "south" || r.pair === "east")) continue;   // an even ridge: build from one of its two rows
    const [x, z] = XZ(r.k), ax = axis.get(r.k) || "x", R = rects.find(([a, b, c, d]) => x >= a && x <= c && z >= b && z <= d);
    if (!R) continue;
    const len = ax === "x" ? R[2] - R[0] + 1 : R[3] - R[1] + 1, along = ax === "x" ? x - R[0] : z - R[1], m = Math.ceil(len * 0.2);
    if (along < m || along > len - 1 - m) continue;
    const [lo, hi] = ax === "x" ? ["north", "south"] : ["west", "east"];
    // the ridge's own cells (one, or two back to back) and the louvre cells either side of them
    const core = r.pair ? [[x, z], step(x, z, OPP[r.pair])] : [[x, z]];
    const ends = [[step(...core.reduce((a, c) => (ZD.has(lo) ? (c[1] < a[1] ? c : a) : c[0] < a[0] ? c : a)), lo), lo], [step(...core.reduce((a, c) => (ZD.has(lo) ? (c[1] > a[1] ? c : a) : c[0] > a[0] ? c : a)), hi), hi]];
    const y = r.yt;
    for (const [[sx, sz], f] of ends) {
      for (const yy of [y, y + 1]) W.put(sx, yy, sz, ["spruce_trapdoor", { facing: f, half: "bottom", open: "true", powered: "false", waterlogged: "false" }]);
      W.put(sx, y + 2, sz, stairs(mat, OPP[f]));
    }
    for (const [cx, cz] of core) { W.put(cx, y + 1, cz, ["air", undefined]); W.put(cx, y + 2, cz, [mat.full, undefined]); if (!r.pair) W.put(cx, y + 3, cz, slab(mat, "bottom")); }
    placed++;
  }
  return placed;
}

// ---- presets: named roofs that are good by construction ---------------------------------------------------------------
