const ALT_ROOF = ["slate", "spruce-shingle", "dark-slate", "red-tile", "dark_oak", "smooth_quartz", "mud_brick"];
const FRONT_FACE = (o) => o.front || "north";
/**
 * Named presets: each scales its proportions to the footprint (the largest wing: span, length, wall height) and
 * returns ordinary roof() options. cottage and shop are steep by design; the others keep the roof no taller than the
 * walls on buildings of two storeys or less. Overhang 1 (2 on spans of 15+).
 */
export const ROOF_PRESETS = {
  cottage: (P) => ({ style: "gable", pitch: P.span <= 11 ? "steep" : 45, steep: true, eave: "flared", material: "spruce", alt: ["dark_oak", "deepslate_tile", "brick"], verge: "dark_oak", ridge: "slab",
    chimneys: [{ at: P.wide ? [P.R[2] - 1, P.R[1] + Math.floor(P.d / 2)] : [P.R[0] + Math.floor(P.w / 2), P.R[3] - 1], material: "cobblestone" }] }),
