  polished_andesite_stairs: "andesite_stairs",
  stripped_spruce_log_stairs: "spruce_stairs", stripped_spruce_log_slab: "spruce_slab",
  dark_oak_stairs: "mangrove_stairs", dark_oak_slab: "mangrove_slab",
