const BRICKS = "bricks", COBBLE = "cobblestone", OAK_PLANKS = "oak_planks", SLOG_OAK = "stripped_oak_log";
const DARK_LOG = "stripped_dark_oak_log", SLOG_SPRUCE = "stripped_spruce_log", SMOOTH_SLAB = "smooth_stone_slab";

